    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_41bd418f24",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e3f0ade479",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "O custo de eventual readequação sem aceite técnico não está definido.",
      "Eventuais diárias de extensão dependem do término novo, que é indeterminado."
    ],
    "motivo": "A cobrança de troca é conhecida, mas o custo total pode incluir itens cujo valor depende de decisão técnica e do prazo final.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "direcao",
    "valor": null,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_41bd418f24",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_259da44f35",
        "localizador": "L03"
      },
      {
        "fonte_id": "f_aa2f56bbb7",
        "localizador": "L03"
      }
    ],
    "lacunas": [
      "Magnitude total não determinável: a cobrança de R$ 200,00 é certa, mas eventual readequação e extensão não têm custo total calculável."
    ],
    "motivo": "Há cobrança adicional expressa de R$ 200,00, não incluída no orçamento, e não há crédito aplicável; o aumento total excede ou iguala essa cobrança, mas sua magnitude não é calculável.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "Comparação isolada com D0. O término e sua variação não podem ser determinados sem aceite técnico, duração de eventual readequação e relações de precedência disponíveis. O custo aumenta devido à cobrança obrigatória de R$ 200,00, mas o total do aumento é indeterminado."
}

